B.a75=new A.aO(57470,"MaterialIcons",!1)
B.ar4=new A.bm([B.b6,"Un amour accompli, une harmonie totale.",B.b7,"La r\xe9ussite compl\xe8te, un cycle couronn\xe9 de succ\xe8s.",B.b8,"Une pl\xe9nitude du corps et de l'esprit.",B.b9,"Le sentiment d'\xeatre exactement \xe0 sa place dans le monde."],t.Q)
